local GrainSpoutMaker = {}
local PRODUCTS = {
    iron_grainspout = { name = "Železni žliv za žito", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni žliv za žito za mlinarje." },
    bronze_grainspout = { name = "Bronast žliv za žito", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast žliv za žito za mlinarje." },
    silver_grainspout = { name = "Srebrn žliv za žito", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn žliv za žito za mlinarje." },
    gilded_grainspout = { name = "Pozlačen žliv za žito", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen žliv za žito za mlinarje." },
    jewel_set_grainspout = { name = "Draguljast žliv za žito", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast žliv za žito za mlinarje." },
    royal_sovereign_grainspout = { name = "Kraljevski suveren žliv za žito", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren žliv za žito z biseri za krono." },
}
local BUILDINGS = {
    grainspout_workshop = { name = "Grainspout delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainspout_house = { name = "Grainspout hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_grainspout_atelier = { name = "Mojstrski grainspout atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainspout_palace = { name = "Suverena grainspout palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainSpoutMaker.ironStock=14; GrainSpoutMaker.bronzeStock=12; GrainSpoutMaker.woodStock=14; GrainSpoutMaker.leatherStock=8; GrainSpoutMaker.silverStock=8; GrainSpoutMaker.goldStock=6; GrainSpoutMaker.jewelStock=4; GrainSpoutMaker.pearlStock=4
GrainSpoutMaker.productStock = {}; GrainSpoutMaker.buildings = {}; GrainSpoutMaker.maker = nil; GrainSpoutMaker.activeMaking = {}; GrainSpoutMaker.totalProducts = 0; GrainSpoutMaker.dayTimer = 0
function GrainSpoutMaker.init() GrainSpoutMaker.ironStock=14; GrainSpoutMaker.bronzeStock=12; GrainSpoutMaker.woodStock=14; GrainSpoutMaker.leatherStock=8; GrainSpoutMaker.silverStock=8; GrainSpoutMaker.goldStock=6; GrainSpoutMaker.jewelStock=4; GrainSpoutMaker.pearlStock=4; GrainSpoutMaker.productStock={}; GrainSpoutMaker.buildings={}; GrainSpoutMaker.maker=nil; GrainSpoutMaker.activeMaking={}; GrainSpoutMaker.totalProducts=0; GrainSpoutMaker.dayTimer=0; print("[GrainSpoutMaker] Royal Grain Spout Maker System initialized (6 products, 4 buildings)") end
function GrainSpoutMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainSpoutMaker.maker={name=n or ("Žlivkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žlivkar najet: %s (spretnost: %d)",GrainSpoutMaker.maker.name,s),"success") end; return true end
function GrainSpoutMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainSpoutMaker.build(id) local ok,e=GrainSpoutMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainSpoutMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainSpoutMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainSpoutMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainSpoutMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainSpoutMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainSpoutMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainSpoutMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainSpoutMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainSpoutMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainSpoutMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainSpoutMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainSpoutMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainSpoutMaker.buildings==0 then return false,"Potrebna žlivna delavnica" end; if not GrainSpoutMaker.maker then return false,"Potreben žlivkar" end; return true end
function GrainSpoutMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainSpoutMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainSpoutMaker.ironStock=GrainSpoutMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainSpoutMaker.bronzeStock=GrainSpoutMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainSpoutMaker.woodStock=GrainSpoutMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainSpoutMaker.leatherStock=GrainSpoutMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainSpoutMaker.silverStock=GrainSpoutMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainSpoutMaker.goldStock=GrainSpoutMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainSpoutMaker.jewelStock=GrainSpoutMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainSpoutMaker.pearlStock=GrainSpoutMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainSpoutMaker.maker then t=math.max(1,t-math.floor(GrainSpoutMaker.maker.skill/13)) end; table.insert(GrainSpoutMaker.activeMaking,{id="grainspout_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainSpoutMaker.completeMaking(m) local q=1.0+(GrainSpoutMaker.getQualityBonus()/100); if GrainSpoutMaker.maker then q=q+(GrainSpoutMaker.maker.skill/140) end; q=math.min(2.5,q); GrainSpoutMaker.productStock[m.productType]=(GrainSpoutMaker.productStock[m.productType] or 0)+m.quantity; GrainSpoutMaker.totalProducts=GrainSpoutMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainSpoutMaker.maker then GrainSpoutMaker.maker.itemsMade=GrainSpoutMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainSpoutMaker.maker.skill=math.min(100,GrainSpoutMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žliv izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainspout.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainSpoutMaker.update(dt) if not _G.state then return end; GrainSpoutMaker.dayTimer=GrainSpoutMaker.dayTimer+dt; if GrainSpoutMaker.dayTimer>=30 then GrainSpoutMaker.dayTimer=0; for i=#GrainSpoutMaker.activeMaking,1,-1 do local m=GrainSpoutMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainSpoutMaker.completeMaking(m); table.remove(GrainSpoutMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainSpoutMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainSpoutMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainSpoutMaker.getStats() return {ironStock=GrainSpoutMaker.ironStock,bronzeStock=GrainSpoutMaker.bronzeStock,woodStock=GrainSpoutMaker.woodStock,leatherStock=GrainSpoutMaker.leatherStock,silverStock=GrainSpoutMaker.silverStock,goldStock=GrainSpoutMaker.goldStock,jewelStock=GrainSpoutMaker.jewelStock,pearlStock=GrainSpoutMaker.pearlStock,productStock=GrainSpoutMaker.productStock,numBuildings=#GrainSpoutMaker.buildings,hasMaker=GrainSpoutMaker.maker~=nil,makerName=GrainSpoutMaker.maker and GrainSpoutMaker.maker.name or "—",makerSkill=GrainSpoutMaker.maker and GrainSpoutMaker.maker.skill or 0,activeMaking=#GrainSpoutMaker.activeMaking,totalProducts=GrainSpoutMaker.totalProducts} end
return GrainSpoutMaker
